Code to build dataset

library(tidyverse)
library(rvest)
nba_url &lt;- "https://www.basketball-reference.com/leagues/NBA_2025_per_poss.html"
nba_players &lt;- nba_url |&gt; 
  read_html() |&gt; 
  html_element(css = "#per_poss") |&gt; 
  html_table() |&gt; 
  janitor::clean_names() |&gt; 
  group_by(player) |&gt; 
  slice_max(g) |&gt; 
  ungroup() |&gt; 
  filter(mp &gt;= 200) # keep players with at least 200 minutes played
